void CatalogSupplemental::registerRoutes(httplib::Server& svr, std::shared_ptr<AuthenticationManager> auth)
{
    svr.Post("/catalogs/{catalog_id}/local_inventory_items/batch", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogscatalogIdlocalInventoryItemsbatchPostRequest(req, res, auth);
    });
    svr.Post("/catalogs/{catalog_id}/local_inventory_items/query", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogscatalogIdlocalInventoryItemsqueryPostRequest(req, res, auth);
    });
    svr.Post("/catalogs/{catalog_id}/local_stores", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogscatalogIdlocalStoresPostRequest(req, res, auth);
    });
    svr.Delete("/catalogs/{catalog_id}/local_stores", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogscatalogIdlocalStoresDeleteRequest(req, res, auth);
    });
    svr.Get("/catalogs/{catalog_id}/local_stores", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogscatalogIdlocalStoresGetRequest(req, res, auth);
    });
    svr.Patch("/catalogs/{catalog_id}/local_stores", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogscatalogIdlocalStoresPatchRequest(req, res, auth);
    });
    svr.Get("/catalogs/{catalog_id}/supplemental_items/batch/{batch_id}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogscatalogIdsupplementalItemsbatchbatchIdGetRequest(req, res, auth);
    });
}

